2	
3	import org.springframework.jdbc.core.JdbcTemplate;
4	import org.springframework.jdbc.core.RowMapper;
5	import org.springframework.stereotype.Repository;
6	
7	import java.util.Optional;
8	
9	/**
10	 * 观测记录持久化：维护 observation_current 当前状态与 observation_version 完整历史快照。
11	 * 所有 SQL 使用参数化查询。
12	 */
13	@Repository
14	public class ObservationRepository {
15	
16	    private static final RowMapper<ObservationSnapshot> SNAPSHOT_MAPPER = (rs, rowNum) -> new ObservationSnapshot(
17	            rs.getString("observation_id"),
18	            rs.getInt("version"),
19	            rs.getString("location"),
20	            rs.getString("reading"),
21	            rs.getString("note"),
22	            rs.getBoolean("deleted"));
23	
24	    private final JdbcTemplate jdbcTemplate;
25	
26	    public ObservationRepository(JdbcTemplate jdbcTemplate) {
27	        this.jdbcTemplate = jdbcTemplate;
28	    }
29	
30	    /**
31	     * 读取当前状态（不加锁），用于查询接口。
32	     */
33	    public Optional<ObservationSnapshot> findCurrent(String observationId) {
34	        return jdbcTemplate.query(
35	                        "SELECT observation_id, version, location, reading, note, deleted "
36	                                + "FROM observation_current WHERE observation_id = ?",
37	                        SNAPSHOT_MAPPER, observationId)
38	                .stream().findFirst();
39	    }
40	
41	    /**
42	     * 读取当前状态并加行锁（SELECT ... FOR UPDATE），用于写事务内串行化同一记录的并发变更。
43	     */
44	    public Optional<ObservationSnapshot> findCurrentForUpdate(String observationId) {
45	        return jdbcTemplate.query(
46	                        "SELECT observation_id, version, location, reading, note, deleted "
47	                                + "FROM observation_current WHERE observation_id = ? FOR UPDATE",
48	                        SNAPSHOT_MAPPER, observationId)
49	                .stream().findFirst();
50	    }
51	
52	    /**
53	     * 读取指定历史版本快照；版本不存在时返回空。
54	     */
55	    public Optional<ObservationSnapshot> findVersion(String observationId, int version) {
56	        return jdbcTemplate.query(
57	                        "SELECT observation_id, version, location, reading, note, deleted "
58	                                + "FROM observation_version WHERE observation_id = ? AND version = ?",
59	                        SNAPSHOT_MAPPER, observationId, version)
60	                .stream().findFirst();
61	    }
62	
63	    /**
64	     * 插入新记录的当前状态（version = 1）。
65	     */
66	    public void insertCurrent(ObservationSnapshot snapshot) {
67	        jdbcTemplate.update(
68	                "INSERT INTO observation_current (observation_id, location, reading, note, version, deleted, updated_at) "
69	                        + "VALUES (?, ?, ?, ?, ?, ?, CURRENT_TIMESTAMP)",
70	                snapshot.observationId(), snapshot.location(), snapshot.reading(), snapshot.note(),
71	                snapshot.version(), snapshot.deleted());
72	    }
73	
74	    /**
75	     * 更新当前状态为新版本内容。
76	     */
77	    public void updateCurrent(ObservationSnapshot snapshot) {
78	        jdbcTemplate.update(
79	                "UPDATE observation_current SET location = ?, reading = ?, note = ?, version = ?, deleted = ?, "
80	                        + "updated_at = CURRENT_TIMESTAMP WHERE observation_id = ?",
81	                snapshot.location(), snapshot.reading(), snapshot.note(),
82	                snapshot.version(), snapshot.deleted(), snapshot.observationId());
83	    }
84	
85	    /**
