3	import org.junit.jupiter.api.BeforeEach;
4	import org.junit.jupiter.api.Test;
5	import org.springframework.beans.factory.annotation.Autowired;
6	import org.springframework.boot.test.context.SpringBootTest;
7	import org.springframework.jdbc.core.JdbcTemplate;
8	
9	import java.util.ArrayList;
10	import java.util.List;
11	import java.util.concurrent.Callable;
12	import java.util.concurrent.CountDownLatch;
13	import java.util.concurrent.ExecutorService;
14	import java.util.concurrent.Executors;
15	import java.util.concurrent.Future;
16	import java.util.concurrent.TimeUnit;
17	
18	import static org.assertj.core.api.Assertions.assertThat;
19	
20	/**
21	 * 并发与幂等边界测试：真实并发提交，验证基于最新版本重新判定、
22	 * 墓碑不被复活、同键并发重放只占一键。
23	 */
24	@SpringBootTest
25	class ObservationConcurrencyTest {
26	
27	    @Autowired
28	    private ObservationService observationService;
29	
30	    @Autowired
31	    private JdbcTemplate jdbcTemplate;
32	
33	    @BeforeEach
34	    void cleanDatabase() {
35	        jdbcTemplate.update("DELETE FROM request_log");
36	        jdbcTemplate.update("DELETE FROM observation_version");
37	        jdbcTemplate.update("DELETE FROM observation_current");
38	    }
39	
40	    private <T> List<T> runConcurrently(List<Callable<T>> tasks) throws Exception {
41	        ExecutorService executor = Executors.newFixedThreadPool(tasks.size());
42	        CountDownLatch ready = new CountDownLatch(tasks.size());
43	        CountDownLatch start = new CountDownLatch(1);
44	        List<Callable<T>> synchronizedTasks = tasks.stream()
45	                .<Callable<T>>map(task -> () -> {
46	                    ready.countDown();
47	                    start.await(10, TimeUnit.SECONDS);
48	                    return task.call();
49	                })
50	                .toList();
51	        try {
52	            List<Future<T>> futures = synchronizedTasks.stream().map(executor::submit).toList();
53	            if (!ready.await(10, TimeUnit.SECONDS)) {
54	                throw new IllegalStateException("workers not ready in time");
55	            }
56	            start.countDown();
57	            List<T> results = new ArrayList<>();
58	            for (Future<T> future : futures) {
59	                results.add(future.get(30, TimeUnit.SECONDS));
60	            }
61	            return results;
62	        } finally {
63	            executor.shutdownNow();
64	        }
65	    }
66	
67	    private void createObservation(String id, String requestId) {
68	        observationService.create(new CreateObservationRequest(requestId, id, "站点A", "1.0", "初始备注"));
69	    }
70	
71	    @Test
72	    void concurrentMergesOnDifferentFieldsBothApply() throws Exception {
73	        createObservation("obs-c1", "req-cc0");
74	
75	        // 两个离线端都基于版本 1：一个改地点，一个改备注；互不冲突，应都生效
76	        List<Callable<ObservationService.WriteOutcome>> tasks = List.of(
77	                () -> observationService.merge("obs-c1",
78	                        new MergeObservationRequest("req-cc1", 1, "站点B", "1.0", "初始备注")),
79	                () -> observationService.merge("obs-c1",
80	                        new MergeObservationRequest("req-cc2", 1, "站点A", "1.0", "并发备注")));
81	        List<ObservationService.WriteOutcome> outcomes = runConcurrently(tasks);
82	
