    void createSameStationSameMinuteReturns409() throws Exception {
        create("req-x4", "exc-1", "ST-A", "2026-10-07T10:00:00Z", "11").andExpect(status().isCreated());
        // 不同 observationId 但同站同分钟：唯一约束冲突
