        mergeBody.put("requestId", "req-v3");
        mergeBody.put("operator", "tester");
        mergeBody.put("baseVersion", 1);
        mergeBody.put("stationId", "ST-1");
        mergeBody.put("minuteUtc", "2026-10-07T10:01:00Z");
        mergeBody.put("reading", "12");
