    @Test
    void sameRequestIdWithDifferentParamsReturns409() throws Exception {
        createObs("req-w1", "obs-z0", "ST-1", "2026-10-07T10:00:00Z", "11");
        createObs("req-w2", "obs-z1", "ST-1", "2026-10-07T10:01:00Z", "11");
